-- L08-K3-daily-bank.sql (run O1, lane L1; generated by apps/quiz/e2e/o1/L1/content-sql.mjs, do not edit by hand)
--
-- What:   37 rows of the anime daily quiz bank (296 questions), status draft, no date. The owner verifies them, then the daily cron files them.
-- Needs:  L04, 009.
-- Verify: select count(*) from public.quiz_bank where site_id = 'anime';   expect 37
-- Undo:   L08-K3-daily-bank.rollback.sql (refused once a row is scheduled or published).
-- o1-transaction: single (psql --single-transaction). Idempotent: a second run changes nothing.

set lock_timeout = '5s';
set client_min_messages = warning;
do $o1l$ begin
  if not exists (select 1 from information_schema.columns where table_schema = 'public' and table_name = 'quiz_bank' and column_name = 'site_id') then
    raise exception 'L08: quiz_bank.site_id is missing (apply 002a first)';
  end if;
end $o1l$;

do $o1l$ begin
  if not exists (select 1 from public.groups where site_id = 'anime' and slug = 'anime-mix') then
    raise exception 'L08: the anime-mix group is missing (apply L04 first)';
  end if;
end $o1l$;

create temp table _k3_bank (title text, description text, group_slug text, quiz_type text, difficulty text, category text, questions jsonb) on commit drop;

insert into _k3_bank values ('Who Am I? Heroes, Hunters and a Rubber Body', 'Eight characters from different series, each introduced by three clues from the very start of their story.', 'anime-mix', 'guess_from_clues', 'easy', 'who_am_i', '[{"question":"Who is this character?","clues":["Swallowed a fruit by mistake","His body turned to rubber","Sails in search of a treasure left by the late King of the Pirates"],"options":["Roronoa Zoro","Monkey D. Luffy","Shanks","Gol D. Roger"],"correct":1,"kind":"character","spoiler":{"arc":0,"scope":"both"},"fact_ids":["one-piece-luffy-rubber-fruit-018","one-piece-roger-treasure-026"],"source_url":"https://en.wikipedia.org/wiki/One_Piece"},{"question":"Who is this character?","clues":["Hunts demons","His sense of smell is unusually sharp","He uses it to sense how other people feel"],"options":["Tanjiro Kamado","Zenitsu Agatsuma","Inosuke Hashibira","Giyu Tomioka"],"correct":0,"kind":"character","spoiler":{"arc":0,"scope":"both"},"fact_ids":["demon-slayer-tanjiro-smell-027"],"source_url":"https://en.wikipedia.org/wiki/List_of_Demon_Slayer:_Kimetsu_no_Yaiba_characters"},{"question":"Who is this character?","clues":["Faces execution unless he meets one condition","He must swallow every one of twenty cursed fingers","They belonged to a legendary King of Curses"],"options":["Yuji Itadori","Megumi Fushiguro","Nobara Kugisaki","Satoru Gojo"],"correct":0,"kind":"character","spoiler":{"arc":0,"scope":"both"},"fact_ids":["jujutsu-kaisen-twenty-fingers-027"],"source_url":"https://en.wikipedia.org/wiki/Jujutsu_Kaisen"},{"question":"Who is this character?","clues":["A human teenager who gains a Soul Reaper''s power","The power was handed over by Rukia Kuchiki","Known as the Substitute Soul Reaper"],"options":["Uryu Ishida","Kisuke Urahara","Yasutora Sado","Ichigo Kurosaki"],"correct":3,"kind":"character","spoiler":{"arc":0,"scope":"both"},"fact_ids":["bleach-ichigo-substitute-020"],"source_url":"https://en.wikipedia.org/wiki/Bleach_(manga)"}